def server_providers(apps, schema_editor):
    """Give every organization that already linked password mailboxes an IMAP provider open to any server, and attach them.

    Such a provider holds no credentials, so this needs only the database (its descriptors are
    stored by the `restore_descriptors` setup job). OAuth mailboxes cannot be attached here (their
    client's id and secret were in a config file the database never saw): they attach to the
    organization's first provider of their kind when an admin creates it.
    """
    MailProvider = apps.get_model("mail", "MailProvider")
    MailAccount = apps.get_model("mail", "MailAccount")
    loose = MailAccount.objects.filter(auth_method="PASSWORD", mail_provider__isnull=True)
    for organization_id in sorted(set(loose.values_list("organization_id", flat=True))):
        provider = MailProvider.objects.create(
            organization_id=organization_id,
            kind="GENERIC",
            name="IMAP / POP3",
            capabilities=["SCHEDULED_SYNC", "SEND"],
            settings={"protocol": None, "incoming": None, "smtp": None, "save_sent_copy": True},
        )
        loose.filter(organization_id=organization_id).update(mail_provider=provider)


